import{_ as o,o as l,c as i,ah as c}from"./chunks/framework.DjU4PSOm.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":3,"title":"오늘 한 것","slug":"오늘-한-것","link":"#오늘-한-것","children":[]},{"level":3,"title":"디버깅 과정 요약","slug":"디버깅-과정-요약","link":"#디버깅-과정-요약","children":[]},{"level":3,"title":"최종 적용한 수정 3가지","slug":"최종-적용한-수정-3가지","link":"#최종-적용한-수정-3가지","children":[]},{"level":3,"title":"배운 것 (일반화된 교훈)","slug":"배운-것-일반화된-교훈","link":"#배운-것-일반화된-교훈","children":[]},{"level":3,"title":"다음 단계","slug":"다음-단계","link":"#다음-단계","children":[]}],"relativePath":"computer/project/Zing/05. RLS 디버깅과 signUp 완성.md","filePath":"computer/project/Zing/05. RLS 디버깅과 signUp 완성.md"}'),d={name:"computer/project/Zing/05. RLS 디버깅과 signUp 완성.md"};function t(a,e,r,s,n,u){return l(),i("div",null,[...e[0]||(e[0]=[c('<h3 id="오늘-한-것" tabindex="-1">오늘 한 것 <a class="header-anchor" href="#오늘-한-것" aria-label="Permalink to &quot;오늘 한 것&quot;">​</a></h3><ul><li><code>lib/auth.ts</code>의 <code>signUp</code> 함수 작성 완료 (Auth 계정 생성 + <code>users</code> 테이블 프로필 저장)</li><li><code>lib/types.ts</code> 완성 (<code>User</code>, <code>Diary</code>, <code>SignUpInput</code>, <code>CreateDiaryInput</code>, <code>UpdateDiaryInput</code>)</li><li>실제 테스트 중 <code>users</code> 테이블 INSERT가 계속 403(RLS 위반)으로 막히는 문제를 끝까지 디버깅</li><li><strong>문제 해결, <code>signUp</code> 실제 동작 확인 완료</strong> — Supabase <code>users</code> 테이블에 실제 row 생성 성공</li></ul><h3 id="디버깅-과정-요약" tabindex="-1">디버깅 과정 요약 <a class="header-anchor" href="#디버깅-과정-요약" aria-label="Permalink to &quot;디버깅 과정 요약&quot;">​</a></h3><ol><li><strong>첫 번째 원인</strong>: <code>users</code> 테이블에 INSERT 정책 자체가 없었음 → 정책 생성</li><li><strong>두 번째 원인(진짜 원인)</strong>: 정책을 만들었는데도 계속 403 → SQL Editor로 직접 정책 내용·세션·<code>auth.uid()</code> 값까지 다 확인했지만 전부 정상 → 정책 조건을 임시로 <code>true</code>(무조건 허용)로 풀어봐도 여전히 막힘 → <strong><code>.insert().select()</code>에서 <code>.select()</code>(조회) 부분에 필요한 SELECT 정책이 없었던 것이 진짜 원인</strong>이었음. INSERT 자체는 처음부터 성공하고 있었고, 결과를 돌려주는 단계에서 막히면서 INSERT 정책 위반과 동일한 에러 메시지가 떠서 계속 엉뚱한 곳을 의심했음.</li><li><strong>덤으로 발견한 버그</strong>: <code>gender</code> 컬럼이 실수로 NOT NULL로 생성되어 있었음 (원래 선택 항목이어야 함) → nullable로 수정</li></ol><h3 id="최종-적용한-수정-3가지" tabindex="-1">최종 적용한 수정 3가지 <a class="header-anchor" href="#최종-적용한-수정-3가지" aria-label="Permalink to &quot;최종 적용한 수정 3가지&quot;">​</a></h3><ol><li><code>users</code> INSERT 정책: <code>with check (auth.uid() = id)</code></li><li><code>users</code> SELECT 정책 신규 추가: <code>using (auth.uid() = id)</code> — &quot;Users can view own profile&quot;</li><li><code>gender</code> 컬럼 <code>NOT NULL</code> → nullable로 변경</li></ol><p>자세한 정책 내용은 <a href="./기능명세서.html">기능명세서.md</a>의 &quot;RLS 정책&quot; 섹션 참고.</p><h3 id="배운-것-일반화된-교훈" tabindex="-1">배운 것 (일반화된 교훈) <a class="header-anchor" href="#배운-것-일반화된-교훈" aria-label="Permalink to &quot;배운 것 (일반화된 교훈)&quot;">​</a></h3><ul><li>Supabase RLS는 <strong>동작(SELECT/INSERT/UPDATE/DELETE)마다 독립적으로 정책이 필요</strong>함. 하나라도 빠지면 그 동작만 막히는데, 에러 메시지가 다른 동작 것과 똑같아서 원인 착각하기 쉬움.</li><li><code>.insert(...).select()</code>처럼 여러 동작을 체이닝하면, 필요한 정책도 그만큼 늘어남 — 이건 초보만 겪는 게 아니라 Supabase 쓰는 개발자들이 흔히 걸리는 함정.</li><li>UI(Table Editor)로 원인이 안 보이면, SQL Editor로 시스템 테이블(<code>pg_policies</code>, <code>information_schema.columns</code>) 직접 조회하고, <code>set local role</code> / <code>set_config</code>로 실제 요청 컨텍스트를 재현해보는 게 표준 디버깅 절차.</li><li>보안을 느슨하게 만드는 시도(정책을 <code>true</code>로 푸는 것 등)는 도구가 자동으로 막아주기도 함 — 이런 임시 테스트가 필요하면 사람이 직접 판단해서 진행해야 함.</li></ul><h3 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h3><ul><li><code>lib/auth.ts</code>에 <code>signIn</code> 함수 추가</li><li><code>lib/diaries.ts</code> 구현 — 단, <strong><code>diaries</code> 테이블도 필요한 정책(INSERT/SELECT/UPDATE/DELETE)을 미리 다 챙길 것</strong> (오늘 겪은 실수 반복 안 하기)</li><li><code>App.tsx</code>의 테스트 코드 정리</li></ul>',11)])])}const g=o(d,[["render",t]]);export{p as __pageData,g as default};
